    /**
     * @method
     * @name dydx#fetchTime
     * @description fetches the current integer timestamp in milliseconds from the exchange server
     * @see https://docs.dydx.xyz/indexer-client/http#get-time
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {int} the current integer timestamp in milliseconds from the exchange server
     */
    public async override Task<Int64> FetchTime(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> response = await this.indexerGetTime(parameters);
        //
        // {
        //     "iso": "2025-07-20T15:12:13.466Z",
        //     "epoch": 1753024333.466
        // }
        //
        return ccxt.BaseExchange.ToInt64Value(this.safeInteger(response, "epoch"));
    }

    public override Dictionary<string, object> parseMarket(object market)
    {
        //
        // {
        //     "clobPairId": "0",
        //     "ticker": "BTC-USD",
        //     "status": "ACTIVE",
        //     "oraclePrice": "118976.5376",
        //     "priceChange24H": "659.9736",
        //     "volume24H": "1292729.3605",
        //     "trades24H": 9387,
        //     "nextFundingRate": "0",
        //     "initialMarginFraction": "0.02",
        //     "maintenanceMarginFraction": "0.012",
        //     "openInterest": "52.0691",
        //     "atomicResolution": -10,
        //     "quantumConversionExponent": -9,
        //     "tickSize": "1",
        //     "stepSize": "0.0001",
        //     "stepBaseQuantums": 1000000,
        //     "subticksPerTick": 100000,
        //     "marketType": "CROSS",
        //     "openInterestLowerCap": "0",
        //     "openInterestUpperCap": "0",
        //     "baseOpenInterest": "50.3776",
        //     "defaultFundingRate1H": "0"
        // }
        //
        string quoteId = "USDC";
        string? marketId = this.safeString(market, "ticker");
        if ((marketId == null))
        {
            throw new ExchangeError ((this.id + " parseMarket() missing marketId")) ;
        }
        List<object> parts = marketId.Split(new [] {"-"}, StringSplitOptions.None).ToList<object>();
        string? baseName = this.safeString(parts, 0);
        string? baseId = this.safeString(market, "baseId", baseName); // idk where 'baseId' comes from, but leaving as is
        string? bs = this.safeCurrencyCode(baseId);
        string? quote = this.safeCurrencyCode(quoteId);
        if (((bs == null)) || ((quote == null)))
        {
            return ccxt.BaseExchange.ToDict(null);
        }
        string settleId = "USDC";
        string? settle = this.safeCurrencyCode(settleId);
        string symbol = ((((bs + "/") + quote) + ":") + settle);
        bool contract = true;
        bool swap = true;
        string? amountPrecisionStr = this.safeString(market, "stepSize");
        string? pricePrecisionStr = this.safeString(market, "tickSize");
        string? status = this.safeString(market, "status");
        bool active = true;
        if (status != "ACTIVE")
        {
            active = false;
        }
        return this.safeMarketStructure(new Dictionary<string, object>() {
            { "id", this.safeString(market, "ticker") },
            { "symbol", symbol },
            { "base", bs },
            { "quote", quote },
            { "settle", settle },
            { "baseId", baseId },
            { "baseName", baseName },
            { "quoteId", quoteId },
            { "settleId", settleId },
            { "type", "swap" },
            { "spot", false },
            { "margin", null },
            { "swap", swap },
            { "future", false },
            { "option", false },
            { "active", active },
            { "contract", contract },
            { "contractSize", this.parseNumber("1") },
            { "linear", true },
            { "inverse", false },
