        //             "trades": 0,
        //             "startingOpenInterest": "54.0594",
        //             "orderbookMidPriceOpen": "115845.5",
        //             "orderbookMidPriceClose": "115845.5"
        //         }
        //     ]
        // }
        //
        List<object> rows = this.safeList(response, "candles", new List<object>() {});
        return ccxt.BaseExchange.ToOHLCVList(this.parseOHLCVs(rows, market,timeframeVar, since, limit));
    }

    /**
     * @method
     * @name dydx#fetchFundingRateHistory
     * @description fetches historical funding rate prices
     * @see https://docs.dydx.xyz/indexer-client/http#get-historical-funding
     * @param {string} symbol unified symbol of the market to fetch the funding rate history for
     * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
     * @param {int} [limit] the maximum amount of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-history-structure} to fetch
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms of the latest funding rate
     * @returns {object[]} a list of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-history-structure}
     */
    public async override Task<List<ccxt.FundingRateHistory>> FetchFundingRateHistory(string symbol = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((symbol == null))
        {
            throw new ArgumentsRequired ((this.id + " fetchFundingRateHistory() requires a symbol argument")) ;
        }
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "market", (market.ContainsKey("id") ? market["id"] : null) },
        };
        if ((limit != null))
        {
            request["limit"] = limit;
        }
        Int64? until = this.safeInteger(parameters, "until");
        if ((until != null))
        {
            request["effectiveBeforeOrAt"] = this.iso8601(until);
        }
        Dictionary<string, object> response = await this.indexerGetHistoricalFundingMarket(this.extend(request, parameters));
        //
        // {
        //     "historicalFunding": [
        //         {
        //             "ticker": "BTC-USD",
        //             "rate": "0",
        //             "price": "116302.62419",
        //             "effectiveAtHeight": "44865196",
        //             "effectiveAt": "2025-07-25T11:00:00.013Z"
        //         }
        //     ]
        // }
        //
        List<object> rates = new List<object>() {};
        List<object> rows = this.safeList(response, "historicalFunding", new List<object>() {});
        for (int i = 0; i < rows.Count; i++)
        {
            object entry = rows[i];
            Int64? timestamp = this.parse8601(this.safeString(entry, "effectiveAt"));
            string? marketId = this.safeString(entry, "ticker");
            rates.Add(new Dictionary<string, object>() {
                { "info", entry },
                { "symbol", this.safeSymbol(marketId, market) },
                { "fundingRate", this.safeNumber(entry, "rate") },
                { "timestamp", timestamp },
                { "datetime", this.iso8601(timestamp) },
            });
        }
        List<object> sorted = this.sortBy(rates, "timestamp");
        return ccxt.BaseExchange.ToFundingRateHistoryList(this.filterBySymbolSinceLimit(sorted, symbol, since, limit));
    }

    public virtual List<object> handlePublicAddress(object methodName, object parameters)
    {
        string? userAux = null;
        IList<object> userAuxparametersVariable = (IList<object>)this.handleOptionStringAndParams(parameters, methodName, "user");
        userAux = (string)userAuxparametersVariable[0];
        parameters = userAuxparametersVariable[1];
        string? user = userAux;
        IList<object> userparametersVariable = (IList<object>)this.handleOptionStringAndParams(parameters, methodName, "address", userAux);
        user = (string)userparametersVariable[0];
        parameters = userparametersVariable[1];
        if (((user != null)) && (user != ""))
        {
            return new List<object>() {user, parameters};
        }
        if (((this.walletAddress != null)) && (!isEqual(this.walletAddress, "")))
        {
            return new List<object>() {this.walletAddress, parameters};
        }
        throw new ArgumentsRequired ((((this.id + " ") + (methodName)) + "() requires a user parameter inside 'params' or the walletAddress set")) ;
    }

    public override Dictionary<string, object> parseOrder(object order, IDictionary<string, object> market = null)
    {
        //
        // {
        //     "id": "dad46410-3444-5566-a129-19a619300fb7",
        //     "subaccountId": "8586bcf6-1f58-5ec9-a0bc-e53db273e7b0",
        //     "clientId": "716238006",
        //     "clobPairId": "0",
        //     "side": "BUY",
        //     "size": "0.001",
        //     "totalFilled": "0.001",
        //     "price": "400000",
        //     "type": "LIMIT",
        //     "status": "FILLED",
        //     "timeInForce": "GTT",
        //     "reduceOnly": false,
        //     "orderFlags": "64",
        //     "goodTilBlockTime": "2025-07-28T12:07:33.000Z",
        //     "createdAtHeight": "45058325",
        //     "clientMetadata": "2",
        //     "updatedAt": "2025-07-28T12:06:35.330Z",
        //     "updatedAtHeight": "45058326",
        //     "postOnly": false,
        //     "ticker": "BTC-USD",
        //     "subaccountNumber": 0
        // }
        //
        string? status = this.parseOrderStatus(this.safeStringUpper(order, "status"));
        string? marketId = this.safeString(order, "ticker");
        string? symbol = this.safeSymbol(marketId, market);
        string? filled = this.safeString(order, "totalFilled");
        Int64? timestamp = this.parse8601(this.safeString(order, "updatedAt"));
        string? price = this.safeString(order, "price");
        string? amount = this.safeString(order, "size");
        string? type = this.parseOrderType(this.safeStringUpper(order, "type"));
        string? side = this.safeStringLower(order, "side");
        string? timeInForce = this.safeStringUpper(order, "timeInForce");
        return this.safeOrder(new Dictionary<string, object>() {
            { "info", order },
            { "id", this.safeString(order, "id") },
            { "clientOrderId", this.safeString(order, "clientId") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", null },
            { "lastUpdateTimestamp", timestamp },
            { "symbol", symbol },
            { "type", type },
            { "timeInForce", timeInForce },
            { "postOnly", this.safeBool(order, "postOnly") },
            { "reduceOnly", this.safeBool(order, "reduceOnly") },
            { "side", side },
            { "price", price },
            { "triggerPrice", null },
            { "amount", amount },
            { "cost", null },
            { "average", null },
            { "filled", filled },
            { "remaining", null },
            { "status", status },
            { "fee", null },
            { "trades", null },
        }, market);
    }

    public virtual string? parseOrderStatus(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "UNTRIGGERED", "open" },
            { "OPEN", "open" },
            { "FILLED", "closed" },
            { "CANCELED", "canceled" },
            { "BEST_EFFORT_CANCELED", "canceling" },
        };
        return this.safeString(statuses, status, status);
    }

    public virtual string? parseOrderType(string? type)
    {
        Dictionary<string, object> types = new Dictionary<string, object>() {
            { "LIMIT", "LIMIT" },
            { "STOP_LIMIT", "LIMIT" },
            { "TAKE_PROFIT_LIMIT", "LIMIT" },
            { "MARKET", "MARKET" },
            { "STOP_MARKET", "MARKET" },
            { "TAKE_PROFIT_MARKET", "MARKET" },
            { "TRAILING_STOP", "MARKET" },
        };
        return this.safeStringUpper(types, type, type);
    }

