            { "info", position },
            { "id", null },
            { "symbol", symbol },
            { "entryPrice", this.safeNumber(position, "entryPrice") },
            { "markPrice", null },
            { "notional", null },
            { "collateral", null },
            { "unrealizedPnl", this.safeNumber(position, "unrealizedPnl") },
            { "side", side },
