    public override Dictionary<string, object> parseLedgerEntry(object item, object currency = null)
    {
        //
        // {
        //     "id": "6a6075bc-7183-5fd9-bc9d-894e238aa527",
        //     "sender": {
        //         "address": "dydx14zzueazeh0hj67cghhf9jypslcf9sh2n5k6art",
        //         "subaccountNumber": 0
        //     },
        //     "recipient": {
        //         "address": "dydx1slanxj8x9ntk9knwa6cvfv2tzlsq5gk3dshml0",
        //         "subaccountNumber": 1
        //     },
        //     "size": "0.000001",
        //     "createdAt": "2025-07-29T09:43:02.105Z",
        //     "createdAtHeight": "45116125",
        //     "symbol": "USDC",
        //     "type": "TRANSFER_OUT",
        //     "transactionHash": "92B4744BA1B783CF37C79A50BEBC47FFD59C8D5197D62A8485D3DCCE9AF220AF"
        // }
        //
        string? currencyId = this.safeString(item, "symbol");
        string? code = this.safeCurrencyCode(currencyId, currency);
        currency = this.safeCurrency(currencyId, currency);
        string? type = this.safeStringUpper(item, "type");
        string? direction = null;
        if ((type != null))
        {
            if (type == "TRANSFER_IN" || type == "DEPOSIT")
            {
                direction = "in";
            } else if (type == "TRANSFER_OUT" || type == "WITHDRAWAL")
            {
                direction = "out";
            }
        }
        string? amount = this.safeString(item, "size");
        Int64? timestamp = this.parse8601(this.safeString(item, "createdAt"));
        IDictionary<string, object> sender = this.safeDict(item, "sender");
        IDictionary<string, object> recipient = this.safeDict(item, "recipient");
        return this.safeLedgerEntry(new Dictionary<string, object>() {
            { "info", item },
            { "id", this.safeString(item, "id") },
            { "direction", direction },
            { "account", this.safeString(sender, "address") },
            { "referenceAccount", this.safeString(recipient, "address") },
            { "referenceId", this.safeString(item, "transactionHash") },
            { "type", this.parseLedgerEntryType(type) },
            { "currency", code },
            { "amount", this.parseNumber(amount) },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "before", null },
            { "after", null },
            { "status", null },
            { "fee", null },
        }, currency);
    }

    public virtual string? parseLedgerEntryType(string? type)
    {
        Dictionary<string, object> ledgerType = new Dictionary<string, object>() {
            { "TRANSFER_IN", "transfer" },
            { "TRANSFER_OUT", "transfer" },
            { "DEPOSIT", "deposit" },
            { "WITHDRAWAL", "withdrawal" },
        };
        return this.safeString(ledgerType, type, type);
    }

    /**
     * @method
     * @name dydx#fetchLedger
     * @description fetch the history of changes, actions done by the user or operations that altered balance of the user
     * @see https://docs.dydx.xyz/indexer-client/http#get-transfers
     * @param {string} [code] unified currency code, default is undefined
     * @param {int} [since] timestamp in ms of the earliest ledger entry, default is undefined
     * @param {int} [limit] max number of ledger entries to return, default is undefined
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.address] wallet address that made trades
     * @param {string} [params.subAccountNumber] sub account number
     * @returns {object} a [ledger structure]{@link https://docs.ccxt.com/?id=ledger-entry-structure}
     */
    public async override Task<List<ccxt.LedgerEntry>> FetchLedger(string code = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
